import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第二十八卦 大過 澤風大過 兌上巽下","description":"周易 - 第二十八卦 大過 澤風大過 兌上巽下","frontmatter":{"title":"第二十八卦 大過 澤風大過 兌上巽下","description":"周易 - 第二十八卦 大過 澤風大過 兌上巽下"},"headers":[],"relativePath":"classics/zhouyi/029.md","filePath":"classics/zhouyi/029.md"}'),l={name:"classics/zhouyi/029.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="大過" tabindex="-1">大過 <a class="header-anchor" href="#大過" aria-label="Permalink to “大過”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>棟橈，利有攸往，亨。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>大過，大者過也。棟橈，本末弱也。剛過而中，巽而說行，利有攸往，乃亨。大過之時義大矣哉！</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>澤滅木，大過；君子以獨立不懼，（辶豚）世無悶。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>藉用白茅，無咎。象曰：藉用白茅，柔在下也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>枯楊生稊，老夫得其女妻，無不利。象曰：老夫女妻，過以相與也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>棟橈，兇。象曰：棟橈之兇，不可以有輔也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>棟隆，吉；有它吝。象曰：棟隆之吉，不橈乎下也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>枯楊生華，老婦得士夫，無咎無譽。象曰：枯楊生華，何可久也。老婦士夫，亦可醜也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>過涉滅頂，兇，無咎。象曰：過涉之兇，不可咎也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
